import sqlite3
import json
from typing import List, Dict, Any, Tuple

# ---- Config (MUST match the provided configuration) ----
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',          # review text embeddings
        'photos': 'photo_vector',      # photo embeddings
        'tips': 'milvus_tip'           # tip text embeddings
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def get_sqlite_conn(db_path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    return conn


def detect_business_schema(conn: sqlite3.Connection) -> List[str]:
    cur = conn.execute("PRAGMA table_info(business)")
    return [r[1] for r in cur.fetchall()]


def step1_candidate_businesses(conn: sqlite3.Connection, limit: int = 2000) -> List[Dict[str, Any]]:
    """Try to filter dinner restaurants with outdoor seating from SQLite."""
    cols = detect_business_schema(conn)

    # Common expected columns in many Yelp SQLite conversions
    needed = ["business_id", "name", "city", "state", "address", "stars", "review_count", "categories"]
    for c in needed:
        if c not in cols:
            raise RuntimeError(f"business table missing expected column: {c}. Found columns: {cols}")

    # attributes column may or may not exist
    has_attributes = "attributes" in cols

    if has_attributes:
        # JSON1 extension is usually available in SQLite builds; if not, this may fail.
        sql = f"""
        SELECT business_id, name, city, state, address, stars, review_count, categories, attributes
        FROM business
        WHERE categories LIKE '%Restaurants%'
          AND (
                json_extract(attributes, '$.GoodForMeal.dinner') IN (1,'1','true','True','TRUE')
                OR json_extract(attributes, '$.GoodForMeal') LIKE '%dinner%true%'
              )
          AND (
                json_extract(attributes, '$.OutdoorSeating') IN (1,'1','true','True','TRUE')
                OR json_extract(attributes, '$.OutdoorSeating') LIKE '%True%'
              )
        LIMIT ?
        """
        try:
            rows = conn.execute(sql, (limit,)).fetchall()
        except sqlite3.OperationalError:
            # Fallback if JSON functions are not available: do text LIKE on attributes
            sql_fallback = f"""
            SELECT business_id, name, city, state, address, stars, review_count, categories, attributes
            FROM business
            WHERE categories LIKE '%Restaurants%'
              AND attributes LIKE '%dinner%'
              AND (attributes LIKE '%OutdoorSeating%True%' OR attributes LIKE '%OutdoorSeating%true%')
            LIMIT ?
            """
            rows = conn.execute(sql_fallback, (limit,)).fetchall()
    else:
        # If no attributes, we can only do categories-based rough filter.
        # Many datasets include 'Dinner' in categories (not guaranteed).
        sql = f"""
        SELECT business_id, name, city, state, address, stars, review_count, categories
        FROM business
        WHERE categories LIKE '%Restaurants%'
          AND (categories LIKE '%Dinner%' OR categories LIKE '%Dinners%')
        LIMIT ?
        """
        rows = conn.execute(sql, (limit,)).fetchall()

    return [dict(r) for r in rows]


def embed_query(text: str) -> List[float]:
    """Create an embedding for the query using sentence-transformers."""
    try:
        from sentence_transformers import SentenceTransformer
        model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
        vec = model.encode([text], normalize_embeddings=True)[0]
        return vec.tolist()
    except Exception as e:
        raise RuntimeError(
            "Embedding failed. Please install sentence-transformers (and torch) or provide your own embedding. "
            f"Original error: {e}"
        )


def milvus_connect():
    from pymilvus import connections
    connections.connect(alias="default", host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])


def _pick_vector_field(collection) -> str:
    # Choose the first FLOAT_VECTOR / BINARY_VECTOR field
    for f in collection.schema.fields:
        t = str(f.dtype)
        if "VECTOR" in t:
            return f.name
    raise RuntimeError(f"No vector field found in collection {collection.name}")


def _has_field(collection, field_name: str) -> bool:
    return any(f.name == field_name for f in collection.schema.fields)


def step2_vector_rooftop_search(candidate_business_ids: List[str], query_text: str, limit: int = 200):
    """Search in Milvus reviews and tips for rooftop patio evidence."""
    from pymilvus import Collection

    milvus_connect()
    qvec = embed_query(query_text)

    results = []  # list of dicts: {collection, business_id, score, text(optional)}

    def search_one_collection(coll_name: str):
        coll = Collection(coll_name)
        coll.load()

        vector_field = _pick_vector_field(coll)

        # We assume there is a scalar field business_id. If not, filtering won't work.
        if not _has_field(coll, "business_id"):
            raise RuntimeError(f"Collection {coll_name} has no 'business_id' field; cannot filter by business.")

        # Build filter expression in Milvus syntax
        # NOTE: large IN lists can be slow; for very large candidate sets, consider batching.
        # Quote strings for Milvus expression.
        ids = [f"\"{bid}\"" for bid in candidate_business_ids]
        expr = f"business_id in [{','.join(ids)}]"

        # Try to retrieve text field if exists
        output_fields = ["business_id"]
        for possible_text_field in ["text", "tip_text", "review_text", "content"]:
            if _has_field(coll, possible_text_field):
                output_fields.append(possible_text_field)
                break

        search_params = {"metric_type": "COSINE", "params": {"ef": 64}}

        try:
            search_res = coll.search(
                data=[qvec],
                anns_field=vector_field,
                param=search_params,
                limit=limit,
                expr=expr,
                output_fields=output_fields
            )
        except Exception:
            # Fallback metric/params
            search_params = {"metric_type": "IP", "params": {"ef": 64}}
            search_res = coll.search(
                data=[qvec],
                anns_field=vector_field,
                param=search_params,
                limit=limit,
                expr=expr,
                output_fields=output_fields
            )

        hits = search_res[0]
        for h in hits:
            entity = getattr(h, "entity", None)
            business_id = None
            text_val = None
            if entity is not None:
                try:
                    business_id = entity.get("business_id")
                except Exception:
                    business_id = None
                for k in output_fields:
                    if k != "business_id":
                        try:
                            text_val = entity.get(k)
                        except Exception:
                            pass
            # Milvus Hit typically has .distance; interpretation depends on metric.
            dist = getattr(h, "distance", None)
            score = None
            if dist is None:
                score = 0.0
            else:
                # Make a monotonic "higher is better" score robustly.
                # For COSINE/IP: dist is similarity (higher better). For L2: lower better.
                # We don't reliably know which is used, so map both ways conservatively.
                # If dist in [-1,1] or [0,1] treat as similarity; otherwise treat as distance.
                if -1.5 <= float(dist) <= 1.5:
                    score = float(dist)
                else:
                    score = 1.0 / (1.0 + float(dist))

            if business_id:
                results.append({
                    "collection": coll_name,
                    "business_id": business_id,
                    "score": score,
                    "text": text_val
                })

        coll.release()

    # Search both reviews and tips
    search_one_collection(milvus_config['milvus_collections']['reviews'])
    search_one_collection(milvus_config['milvus_collections']['tips'])

    return results


def step3_merge_and_rank(candidate_businesses: List[Dict[str, Any]], rooftop_hits: List[Dict[str, Any]], topk: int = 20):
    # Aggregate best rooftop score per business_id, keep top evidence snippet if available
    agg: Dict[str, Dict[str, Any]] = {}
    for h in rooftop_hits:
        bid = h["business_id"]
        if bid not in agg or h["score"] > agg[bid]["rooftop_score"]:
            agg[bid] = {
                "rooftop_score": h["score"],
                "evidence_collection": h.get("collection"),
                "evidence_text": h.get("text")
            }

    # Join with business info
    by_id = {b["business_id"]: b for b in candidate_businesses}
    merged = []
    for bid, ev in agg.items():
        b = by_id.get(bid)
        if not b:
            continue
        merged.append({
            **{k: b.get(k) for k in b.keys()},
            **ev
        })

    # Rank: rooftop evidence first, then stars, then review_count
    def safe_float(x, default=0.0):
        try:
            return float(x)
        except Exception:
            return default

    def safe_int(x, default=0):
        try:
            return int(x)
        except Exception:
            return default

    merged.sort(key=lambda r: (
        safe_float(r.get("rooftop_score"), 0.0),
        safe_float(r.get("stars"), 0.0),
        safe_int(r.get("review_count"), 0)
    ), reverse=True)

    return merged[:topk]


def main():
    query_text = "dinner restaurant with a rooftop patio"

    # Step 1: SQLite candidates
    conn = get_sqlite_conn(sqlite_paths["business"])
    try:
        candidates = step1_candidate_businesses(conn, limit=3000)
    finally:
        conn.close()

    if not candidates:
        print("No candidates found from SQLite filters. You may need to relax filters or adjust schema assumptions.")
        return

    candidate_ids = [c["business_id"] for c in candidates]

    # Step 2: Vector search evidence
    rooftop_hits = step2_vector_rooftop_search(
        candidate_business_ids=candidate_ids,
        query_text=query_text,
        limit=200
    )

    if not rooftop_hits:
        print("No rooftop-related vector hits found in Milvus for the candidate set.")
        return

    # Step 3: Merge + Rank
    ranked = step3_merge_and_rank(candidates, rooftop_hits, topk=20)

    # Output
    print("Top dinner restaurants with rooftop patio evidence:\n")
    for i, r in enumerate(ranked, 1):
        name = r.get("name")
        city = r.get("city")
        state = r.get("state")
        stars = r.get("stars")
        review_count = r.get("review_count")
        score = r.get("rooftop_score")
        addr = r.get("address")
        print(f"{i}. {name} | {city}, {state} | stars={stars} reviews={review_count} | rooftop_score={score:.4f}")
        if addr:
            print(f"   address: {addr}")
        if r.get("evidence_text"):
            txt = str(r.get("evidence_text"))
            txt = txt.replace("\n", " ").strip()
            if len(txt) > 220:
                txt = txt[:220] + "..."
            print(f"   evidence({r.get('evidence_collection')}): {txt}")
        print()


if __name__ == "__main__":
    main()
